  symbolism:
    "このカードの中心的なテーマは『新しい愛』と『心を開くこと』です。閉じていた心が少しずつ開き、愛情や信頼を受け入れる過程として解釈できます。実際のカード画像に描かれた色彩やモチーフについては、画像を確認したうえで具体的な象徴の説明を追加します。",
