    message: "あなたの心には、まだ気づいていない強さがあります。恐れがあるからこそ、勇気には意味があります。自分の中に灯る小さな炎を信じ、その光を頼りに一歩を踏み出してください。",
    advice: "挑戦したいことを一つ選び、今日できる小さな行動に分けてみましょう。不安を感じたら、何が心配なのかを書き出し、準備できることを整理してください。勇気を勢いだけに頼らず、休息や周囲の助けも取り入れながら、無理のない歩幅で進むことが大切です。",
    learningTip: "このカードを学ぶときは、「勇気」と「無謀」の違いに注目しましょう。勇気は恐れを認めたうえで、目的や状況を考えながら行動する力です。鑑定では、相談者が何に不安を感じ、どのような一歩なら現実的に踏み出せるかを考えます。特に恋愛では相手への配慮、仕事では準備と計画性を組み合わせて解釈すると、実践的なアドバイスにつながります。",
