    advice: "最近気になっている出来事や、負担に感じていることを紙に書き出してみましょう。その中から、自分で変えられること、誰かに相談できること、今は答えを急がなくてよいことを分けて考えてください。身の回りの整理や生活習慣の見直しなど、取り組みやすい行動を一つ選ぶのもよいでしょう。また、気持ちが揺れているときには、無理に前向きになろうとせず、十分な休息を取ることも大切です。",
    learningTip: "このカードを学ぶときは、「浄化」を単純な幸運の到来や、過去の問題が自動的に解決するという意味で捉えないことが重要です。浄化の雨が示すのは、感情や状況を整理し、変化を受け入れるための過程です。鑑定では、相談者が何を手放したいと感じているのか、何を大切に残したいのかを丁寧に考えましょう。恋愛では過去の経験と現在の関係を区別し、仕事では習慣や方法の見直し、総合運では生活と感情の整理に注目します。また、相談者に無理な忘却や許しを求めず、本人の意思とペースを尊重することが大切です。",
